  const norm = (l: string[]) => l.map((x) => (T.includes(x) ? x : "X")).join(",");
  for (const [name, fn] of Object.entries(rules)) {
    const got = norm(fn({ T, C, S }));
    if (got !== obs.join(",")) (score[name] ??= []).push(`${r.id}(${obs.join(",")}|${got})`);
  }
}
console.log("cases", f.length);
for (const n of Object.keys(rules)) console.log(n, "fails", (score[n] ?? []).length, (score[n] ?? []).slice(0, 12).join(" "));
EOF
cd /work && node --disable-warning=ExperimentalWarning /tmp/an/score.ts

